// Java and Python reference solutions as plain files (plan 0063). Files: packages/shared/content/solutions/<problem-id>.java|.py
//   pnpm solutions:build              write packages/shared/src/judge/generated/solutions.ts (only the lead runs this, at the end)
//   pnpm solutions:check              fail when the generated file is stale or a file name is not a problem id / .java / .py
//   pnpm solutions:status [group]     done/total per language for groups d, e, f, and the missing ids
//   pnpm solutions:todo <group> [--limit 10]   the next problems without both files: starters and the C++ reference
// Rules and examples: docs/solutions.md. The file helpers are pure (no TypeScript imports) so a test can use them.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const SOLUTIONS_DIR = path.join(root, "packages/shared/content/solutions");
export const GENERATED_FILE = path.join(root, "packages/shared/src/judge/generated/solutions.ts");
export const SKIP_STRESS_LINE = "# verify: skip-stress";
const EXT = { ".java": "java", ".py": "python" };

/**
 * Reads the solution folder.
 * @returns {{ files: { id: string; lang: "java" | "python"; name: string; code: string }[]; errors: string[] }}
 */
export function readSolutionFiles(dir = SOLUTIONS_DIR) {
  const files = [];
  const errors = [];
  if (!fs.existsSync(dir)) return { files, errors };
  for (const name of fs.readdirSync(dir).sort()) {
    if (name === "README.md") continue;
    const full = path.join(dir, name);
    if (!fs.statSync(full).isFile()) {
      errors.push(`${name}: only files are allowed in the solutions folder`);
      continue;
    }
    const ext = path.extname(name);
    const lang = EXT[ext];
    if (!lang) {
      errors.push(`${name}: extension must be .java or .py`);
      continue;
    }
    const id = name.slice(0, -ext.length);
    files.push({ id, lang, name, code: fs.readFileSync(full, "utf8").replace(/\r\n?/g, "\n") });
  }
  return { files, errors };
}

/** The generated TypeScript for the given files. Deterministic: sorted by id, java before python. */
export function renderGenerated(files) {
  /** @type {Record<string, { java?: string; python?: string }>} */
  const by = {};
  for (const f of files) (by[f.id] ??= {})[f.lang] = f.code;
  const ids = Object.keys(by).sort();
  const head = `// Generated by scripts/solutions.mjs from packages/shared/content/solutions/. Do not edit; run \`pnpm solutions:build\`.
export const SOLUTIONS: Record<string, { java?: string; python?: string }> = `;
  if (!ids.length) return `${head}{};\n`;
  const rows = ids.map((id) => {
    const parts = ["java", "python"].filter((l) => by[id][l] !== undefined).map((l) => `${l}: ${JSON.stringify(by[id][l])}`);
    return `  ${JSON.stringify(id)}: { ${parts.join(", ")} },`;
  });
  return `${head}{\n${rows.join("\n")}\n};\n`;
}

/** Problems in the folder that are not known ids, plus bad extensions. */
export function checkFiles(files, folderErrors, knownIds) {
  const errors = [...folderErrors];
  for (const f of files) if (!knownIds.has(f.id)) errors.push(`${f.name}: "${f.id}" is not a problem id`);
  return errors;
}

/** True when generated/solutions.ts matches the files. */
export function generatedIsCurrent(dir = SOLUTIONS_DIR, generated = GENERATED_FILE) {
  const { files, errors } = readSolutionFiles(dir);
  if (errors.length) return false;
  return fs.existsSync(generated) && fs.readFileSync(generated, "utf8").replace(/\r\n/g, "\n") === renderGenerated(files);
}

/** Status of one group: ids missing Java or Python, from the files on disk. */
export function groupStatus(ids, files) {
  const has = { java: new Set(), python: new Set() };
  for (const f of files) has[f.lang].add(f.id);
  return {
    total: ids.length,
    java: ids.filter((i) => has.java.has(i)).length,
    python: ids.filter((i) => has.python.has(i)).length,
    missing: ids.filter((i) => !has.java.has(i) || !has.python.has(i)),
    missingJava: ids.filter((i) => !has.java.has(i)),
    missingPython: ids.filter((i) => !has.python.has(i)),
    skipStress: files.filter((f) => f.lang === "python" && ids.includes(f.id) && f.code.split("\n")[0].trim() === SKIP_STRESS_LINE).map((f) => f.id),
  };
}

async function loadTs() {
  const shared = await import("@habit/shared");
  const groups = await import("../packages/shared/src/judge/solution-groups.ts");
  return { JUDGE_PROBLEMS: shared.JUDGE_PROBLEMS, templateFor: shared.templateFor, ...groups };
}

function starter(templateFor, spec, lang) {
  try {
    const t = templateFor(spec, lang);
    if (typeof t === "string" && t.trim()) return t;
  } catch {
    /* language not supported by the templates yet */
  }
  return null;
}

async function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  if (cmd === "build" || cmd === "check") {
    const { files, errors } = readSolutionFiles();
    const { JUDGE_PROBLEMS } = await loadTs();
    const bad = checkFiles(files, errors, new Set(Object.keys(JUDGE_PROBLEMS)));
    if (cmd === "build") {
      if (bad.length) {
        console.error(`Solution problems (${bad.length}):\n${bad.map((b) => `  ${b}`).join("\n")}`);
        process.exit(1);
      }
      const out = renderGenerated(files);
      const have = fs.existsSync(GENERATED_FILE) ? fs.readFileSync(GENERATED_FILE, "utf8") : "";
      if (have !== out) fs.writeFileSync(GENERATED_FILE, out);
      console.log(`Built ${files.length} solution files into packages/shared/src/judge/generated/solutions.ts`);
      return;
    }
    if (!generatedIsCurrent()) bad.push("generated/solutions.ts is out of date. Run: pnpm solutions:build");
    if (bad.length) {
      console.error(`Solution problems (${bad.length}):\n${bad.map((b) => `  ${b}`).join("\n")}`);
      process.exit(1);
    }
    console.log(`Solutions OK: ${files.length} files.`);
    return;
  }
  if (cmd === "status" || cmd === "todo") {
    const { SOLUTION_GROUP_IDS, groupIds } = await loadTs();
    const group = rest.find((a, i) => !a.startsWith("-") && rest[i - 1] !== "--limit");
    if (group && !SOLUTION_GROUP_IDS.includes(group)) {
      console.error(`Unknown group "${group}". Use one of: ${SOLUTION_GROUP_IDS.join(", ")}`);
      process.exit(2);
    }
    const { files } = readSolutionFiles();
    if (cmd === "status") {
      for (const g of group ? [group] : SOLUTION_GROUP_IDS) {
        const s = groupStatus(groupIds(g), files);
        const pct = (n) => `${n}/${s.total} (${Math.round((n / (s.total || 1)) * 100)}%)`;
        console.log(`group ${g}: java ${pct(s.java)}, python ${pct(s.python)}`);
        if (group) {
          if (s.missingJava.length) console.log(`  missing java (${s.missingJava.length}): ${s.missingJava.join(", ")}`);
          if (s.missingPython.length) console.log(`  missing python (${s.missingPython.length}): ${s.missingPython.join(", ")}`);
        }
        if (s.skipStress.length) console.log(`  python skip-stress (${s.skipStress.length}): ${s.skipStress.join(", ")}`);
      }
      return;
    }
    if (!group) {
      console.error("Usage: pnpm solutions:todo <group d|e|f> [--limit 10]");
      process.exit(2);
    }
    const li = rest.indexOf("--limit");
    const limit = li >= 0 ? Number(rest[li + 1]) : 10;
    if (!Number.isInteger(limit) || limit < 1) {
      console.error("--limit needs a positive whole number");
      process.exit(2);
    }
    const { JUDGE_PROBLEMS, templateFor } = await loadTs();
    const s = groupStatus(groupIds(group), files);
    const next = s.missing.slice(0, limit);
    if (!next.length) {
      console.log(`Group ${group} is complete.`);
      return;
    }
    console.log(`Group ${group}: ${s.missing.length} problems still need a Java or Python file. Next ${next.length}:\n`);
    const have = new Set(files.map((f) => `${f.id}.${f.lang}`));
    for (const id of next) {
      const spec = JUDGE_PROBLEMS[id];
      const need = [!have.has(`${id}.java`) && `${id}.java`, !have.has(`${id}.python`) && `${id}.py`].filter(Boolean);
      console.log(`${"=".repeat(78)}\n${id}: ${spec.title}\nWrite: ${need.join(", ")}\n`);
      console.log(`--- Java starter ---\n${starter(templateFor, spec, "java") ?? "(none)"}`);
      const py = starter(templateFor, spec, "python");
      const shape = spec.design ? `class ${spec.design.className} with __init__ and the methods` : `class Solution with the method named exactly ${spec.fn.name} and typing annotations`;
      console.log(`--- Python starter ---\n${py ?? `(NOTE: the Python starter is not generated yet. Follow the plan 0062 shape: ${shape}.)\n`}`);
      console.log(`--- C++ reference ---\n${spec.solution.cpp}`);
    }
    return;
  }
  console.error("Usage: node scripts/solutions.mjs build | check | status [group] | todo <group> [--limit N]");
  process.exit(2);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
